window.RP_SESSION={"id":"S-1698bbcaf7cb","messages":[{"id":"RP-II-0072175","time":"2026-03-30T08:53:00+09:00","room":"RP II","name":"햄 찌","profile":"햄 찌","identity":"unresolved","type":"dialogue","body":"\"허...\"\n\n길드 마당에 앉아 사과를 깎고 있는 그\n\n상당히 능숙하게, 사과 껍질을 모두 벗겨내고서는 6등분 해 접시에 담고서 가져간다.\n\n\"드실 분들은 드쇼.\"","characters":[]},{"id":"RP-II-0072176","time":"2026-03-30T08:58:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"맥주안주로 딱이구먼~!\"\n\n아삭아삭한 사과를 맥주안주로 먹고있는 라르손","characters":["P-b551ad21c43a"]},{"id":"RP-II-0072177","time":"2026-03-30T08:59:00+09:00","room":"RP II","name":"햄 찌","profile":"햄 찌","identity":"unresolved","type":"dialogue","body":"\"...아침부터 맥주라니, 피 대신 맥주가 흐르겠구만.\"","characters":[]},{"id":"RP-II-0072178","time":"2026-03-30T09:00:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하하, 드워프들은 다그런다네!\"\n\n검증된사실이 아닙니다.\n\n\"자네도 한잔하겠나?\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0072179","time":"2026-03-30T09:01:00+09:00","room":"RP II","name":"햄 찌","profile":"햄 찌","identity":"unresolved","type":"dialogue","body":"\"아니, 난 됐네. 하루종일 숙취를 달고 살 생각을 하니 벌써부터 어지럽군.\"","characters":[]},{"id":"RP-II-0072180","time":"2026-03-30T09:02:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"으하하하, 맥주!\"\n\n맥주를마시며 떠나는 라르손~","characters":["P-b551ad21c43a"]},{"id":"RP-II-0072181","time":"2026-03-30T09:04:00+09:00","room":"RP II","name":"햄 찌","profile":"햄 찌","identity":"unresolved","type":"dialogue","body":"문득 맥주가 발명되지 않았다면, 드워프들은 뭘 마시고 살았을지 의문이 든다...","characters":[]},{"id":"RP-II-0072182","time":"2026-03-30T20:41:00+09:00","room":"RP II","name":"Maria Anaïs Ésther","profile":"Maria Anaïs Ésther","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0072183","time":"2026-03-30T20:41:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
